      #panel-gk .gk-c-left{{flex:1;min-width:0;}}
      #panel-gk .gk-mail{{color:var(--gkd);font-size:12.5px;font-weight:700;text-decoration:none;}}
      #panel-gk .gk-mail:hover{{text-decoration:underline;}}
